usage.code:
import { DepthCarousel } from "solen-design/react";

const items = [
  "/photos/one.jpg",
  { image: "/photos/two.jpg", alt: "Second slide" },
  "/photos/three.jpg",
  "/photos/four.jpg",
  "/photos/five.jpg",
  "/photos/six.jpg"
];

<DepthCarousel
  items={items}
  cardWidth={300}
  cardHeight={380}
  radius={18}
  tint="#05060a"
  depth={220}
  spread={90}
  tilt={22}
  tiltDirection="right"
  perspective={1400}
  visibleCards={4}
  falloff={0.2}
  blur={6}
  duration={700}
  autoplay={false}
  autoplayDelay={3200}
  loop={true}
  showControls={true}
  showIndicators={true}
  onChange={(index, item) => console.log(index, item)}
/>
